#include <bits/stdc++.h>
using namespace std;
#define int long long
int sum(int a, int b, int n, vector<int>& pre){
    if(a*3+(b*3)/2<=3*n)
    return 3*pre[3*n-(2*a+(b/2))] + pre[a+b] + 2*pre[a];
    else return 0;
}
int32_t main() {
	// your code goes here
    int t;
    cin>>t;
    while(t--){
        int n;
        cin>>n;
        int a[3*n+1];
        for(int i=1;i<=3*n;i++){
            cin>>a[i];
        }
        sort(a+1,a+3*n+1);
        reverse(a+1,a+3*n+1);
        vector<int> pre(3*n+1,0);
        pre[0]=0;
        for(int i=1;i<=3*n;i++){
            pre[i] = pre[i-1] + a[i];
        }
        int ans=0;
        for(int i=0;i<=n;i++){
            int l = 0, r= (n-i),x1,x2;
            int cur = sum(i,0,n,pre);
            while(r-l>=3){
                x1 = l + (r-l)/3;
                x2 = r - (r-l)/3;
                int b1 = 2*x1;
                int b2 = 2*x2;
                int s1 = sum(i,b1,n,pre);
                int s2 = sum(i,b2,n,pre);
                if(s1>=s2){
                    r = x2;
                    cur= max(cur,s1);
                }
                else{
                    l = x1;
                    cur = max(cur,s2);
                }
            }
            
            ans = max(ans,cur);
            ans = max(ans,sum(i,2*l,n,pre));
            ans = max(ans,sum(i,2*(l+1),n,pre));
            ans = max(ans,sum(i,2*(l+2),n,pre));
        }
        cout<<ans<<"\n";
    }
}
